// frontend/src/pages/Home.jsx
import React from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Home = () => {
  const { user } = useAuth();
  return (
    <div className="container mx-auto p-8 text-center">
      <h1 className="text-4xl font-bold mb-4">Hệ thống định giá và thu mua ô tô cũ</h1>
      <p className="text-lg mb-6">Công nghệ AI giúp định giá chính xác, nhanh chóng</p>
      {!user && (
        <div className="space-x-4">
          <Link to="/register" className="bg-blue-500 text-white px-6 py-2 rounded">Đăng ký ngay</Link>
          <Link to="/login" className="bg-gray-500 text-white px-6 py-2 rounded">Đăng nhập</Link>
        </div>
      )}
    </div>
  );
};

export default Home;
